SELECT gd.group_deal_id, gd.title, gd.sub_title, gd.origin_price, gd.deal_price, gd.discount_rate, gd.current_quantity, gd.min_member_count, gd.status, gd.end_at, -- 대표 이미지 (sort_order = 1) gi.image_url AS thumbnail_image_url FROM GROUP_DEAL gd LEFT JOIN GROUP_DEAL_IMAGE gi ON gd.group_deal_id = gi.group_deal_id AND gi.sort_order = 1 WHERE gd.is_active = 'Y'
AND gd.status = #{status}
ORDER BY gd.end_at ASC

SELECT NVL(SUM(quantity), 0)
FROM GROUP_DEAL_MEMBER
WHERE group_deal_id = #{groupDealId}
  AND user_id = #{userId}

mapper.update:
UPDATE GROUP_DEAL
SET current_quantity = current_quantity + #{quantity}
WHERE group_deal_id = #{groupDealId}
